 '<section class="page"><header class="page-head"><div class="mini-brand">H <span>HYDRO STAR</span></div><span>PROPOSTA COMERCIAL</span></header><div class="page-title"><span>05 / CONDIÇÕES</span><h2>CONDIÇÕES COMERCIAIS</h2><p>Informações para alinhamento da execução</p></div><div class="conditions"><div class="condition"><span>VALIDADE DA PROPOSTA</span><strong>7 dias</strong></div><div class="condition"><span>PRAZO DE ENTREGA</span><strong>'+deadline+'</strong></div><div class="condition"><span>GARANTIA DA INSTALAÇÃO</span><strong>'+text(company.installationWarranty||"3 meses")+'</strong></div><div class="condition"><span>EQUIPAMENTOS</span><strong>'+text(company.equipmentWarranty||"Garantia do fabricante")+'</strong></div></div><div class="address-card"><h3>Dados do cliente</h3><strong>'+customer+'</strong><p>'+text(q.customerPhone||client.phone||"Telefone não informado")+'</p><p>'+text(client.email||"")+'</p><p>'+text(address||"Endereço não informado")+'</p></div><div class="company-card"><div class="mini-brand">H <span>HYDRO STAR</span></div><p>CNPJ: '+text(company.cnpj)+'</p><p>WhatsApp: '+text(company.phone)+'</p><p>E-mail: '+text(company.email)+'</p><p>Atendimento em dias úteis, das 8h às 17h30.</p></div><div class="closing">Fascinação por excelência, segurança e pontualidade.</div><div class="signature"><span>Responsável: '+responsible+'</span><span>Data: '+quoteDate+'</span></div><div class="page-foot"><span>Obrigado pela confiança.</span><span>#HydroStarExperience</span></div></section>';
 const popup=window.open("","_blank");
 if(!popup){alert("O navegador bloqueou a janela do PDF. Permita pop-ups para este site e tente novamente.");return}
 popup.document.open();
