function quotesPage(){let items=state.quotes.filter(q=>(q.title+" "+clientName(q.clientId)+" "+q.status).toLowerCase().includes(state.search.toLowerCase())&&(state.filter==="all"||q.status===state.filter));let rows=items.map(q=>'<tr><td><strong>'+esc(q.title)+'</strong><br><span class="muted small">'+esc(clientName(q.clientId))+'</span></td><td>'+date(q.date)+'</td><td>'+statusTag(q.status)+'</td><td><strong>'+money(q.value)+'</strong></td><td><button class="btn smallbtn" data-pdf-quote="'+q.id+'">Gerar PDF</button> <button class="btn smallbtn" data-edit="quote" data-id="'+q.id+'">Editar</button> <button class="btn smallbtn danger" data-delete="quote" data-id="'+q.id+'">Excluir</button></td></tr>').join("");return '<div class="welcome"><div><h2>Orçamentos</h2><div class="muted">Registre serviços, valores e acompanhe a decisão do cliente.</div></div></div>'+searchBar("Buscar por serviço ou cliente…","new-quote",'<select class="filter" id="filterSelect"><option value="all">Todos os status</option>'+["Pendente","Enviado","Aprovado","Cancelado"].map(x=>'<option '+(state.filter===x?"selected":"")+'>'+x+'</option>').join("")+'</select>')+'<section class="panel">'+(rows?table(["Orçamento / cliente","Data","Status","Valor","Ações"],rows):empty("▤","Nenhum orçamento encontrado","Crie um orçamento para acompanhar a negociação.","new-quote","＋ Novo orçamento"))+'</section>'}
function servicesPage(){
const selected=state.agendaDate||today();
const selectedDate=new Date(selected+"T12:00:00");
const monthStart=new Date(state.agendaYear,state.agendaMonth,1);
const monthLabel=monthStart.toLocaleDateString("pt-BR",{month:"long",year:"numeric"});
const dayItems=state.services.filter(s=>s.date===selected&&s.status!=="Cancelado").sort((a,b)=>(a.time||"").localeCompare(b.time||""));
const items=state.services.filter(s=>(s.title+" "+clientName(s.clientId)+" "+s.status+" "+(s.address||s.customerAddress||"")).toLowerCase().includes(state.search.toLowerCase())&&(state.filter==="all"||s.status===state.filter));
const rows=items.map(s=>'<tr><td><strong>'+esc(s.title)+'</strong><br><span class="muted small">'+esc(clientName(s.clientId))+'</span></td><td>'+date(s.date)+'</td><td>'+statusTag(s.status)+'</td><td>'+esc(s.technician||"—")+'</td><td>'+money(s.value)+'</td><td><button class="btn smallbtn" data-edit="service" data-id="'+s.id+'">Editar</button> <button class="btn smallbtn danger" data-delete="service" data-id="'+s.id+'">Excluir</button></td></tr>').join("");
const routeStops=dayItems.filter(s=>(s.address||s.customerAddress||state.clients.find(c=>c.id===s.clientId)?.address||"").trim());
const addresses=routeStops.map(s=>{const quote=state.quotes.find(q=>q.id===s.quoteId)||{};const client=state.clients.find(c=>c.id===s.clientId)||state.clients.find(c=>c.id===quote.clientId)||{};const address=(s.address||s.customerAddress||quote.customerAddress||client.address||"").trim();const postalCode=s.postalCode||quote.postalCode||client.postalCode||"";const neighborhood=s.neighborhood||quote.neighborhood||client.neighborhood||"";const city=s.city||quote.city||client.city||"";const stateCode=s.state||quote.state||client.state||"";return {service:s,address,geocodeQuery:[address,neighborhood,city,stateCode,postalCode,"Brasil"].filter(Boolean).join(", "),postalCode,neighborhood,city,state:stateCode}});
const routeUrl=addresses.length? "https://www.google.com/maps/dir/?api=1&destination="+encodeURIComponent(addresses[addresses.length-1].geocodeQuery||addresses[addresses.length-1].address)+(addresses.length>1?"&origin="+encodeURIComponent(addresses[0].geocodeQuery||addresses[0].address)+"&waypoints="+encodeURIComponent(addresses.slice(1,-1).map(x=>x.geocodeQuery||x.address).join("|")):"&query="+encodeURIComponent(addresses[0].geocodeQuery||addresses[0].address)):"";
const daysInMonth=new Date(state.agendaYear,state.agendaMonth+1,0).getDate();
const offset=(new Date(state.agendaYear,state.agendaMonth,1).getDay()+6)%7;
const dayCounts={};state.services.filter(s=>s.date&&s.status!=="Cancelado").forEach(s=>dayCounts[s.date]=(dayCounts[s.date]||0)+1);
let calendarCells="";
for(let i=0;i<offset;i++)calendarCells+='<div class="calendar-cell muted calendar-empty"></div>';
for(let d=1;d<=daysInMonth;d++){const key=state.agendaYear+"-"+String(state.agendaMonth+1).padStart(2,"0")+"-"+String(d).padStart(2,"0");calendarCells+='<button class="calendar-cell '+(key===selected?"selected":"")+' '+(key===today()?"today":"")+'" data-agenda-date="'+key+'"><span>'+d+'</span>'+(dayCounts[key]?'<small>'+dayCounts[key]+' serviço(s)</small>':'')+'</button>'}
const agendaCards=dayItems.map(s=>{const address=(s.address||s.customerAddress||state.clients.find(c=>c.id===s.clientId)?.address||"").trim();return '<article class="agenda-card"><div class="agenda-time">'+esc(s.time||"Sem horário")+'</div><div class="agenda-info"><strong>'+esc(s.title||"Atendimento")+'</strong><div class="muted small">'+esc(clientName(s.clientId))+' · '+statusTag(s.status)+'</div><div class="small">'+esc(address||"Endereço não informado")+'</div><div class="muted small">Técnico: '+esc(s.technician||"Não definido")+'</div></div><button class="btn smallbtn" data-edit="service" data-id="'+s.id+'">Abrir</button></article>'}).join("");
const mapCards=addresses.map((x,i)=>'<div class="map-stop"><span class="map-number">'+(i+1)+'</span><div><strong>'+esc(x.service.title||"Atendimento")+'</strong><div class="muted small">'+esc(clientName(x.service.clientId))+'</div><div class="small">'+esc(x.address)+'</div></div><a class="btn smallbtn" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(x.geocodeQuery||x.address)+'">Ver no mapa</a></div>').join("");
const tabs='<div class="agenda-tabs"><button class="btn '+(state.agendaView==="day"?"primary":"")+'" data-agenda-view="day">Agenda diária</button><button class="btn '+(state.agendaView==="calendar"?"primary":"")+'" data-agenda-view="calendar">Calendário mensal</button><button class="btn '+(state.agendaView==="map"?"primary":"")+'" data-agenda-view="map">Mapa do dia</button></div>';
const calendar='<section class="panel"><div class="calendar-head"><button class="btn" data-month-shift="-1" aria-label="Mês anterior">‹</button><h3>'+esc(monthLabel.charAt(0).toUpperCase()+monthLabel.slice(1))+'</h3><button class="btn" data-month-shift="1" aria-label="Próximo mês">›</button><button class="btn smallbtn" data-agenda-today>Hoje</button></div><div class="calendar-grid calendar-weekdays">'+["Seg","Ter","Qua","Qui","Sex","Sáb","Dom"].map(d=>'<div>'+d+'</div>').join("")+'</div><div class="calendar-grid">'+calendarCells+'</div><p class="muted small">Os números nos dias indicam quantas ordens de serviço estão agendadas.</p></section>';
const daily='<section class="panel"><div class="panel-head"><div><h3>Agenda do dia</h3><div class="muted small">'+date(selected)+' · '+dayItems.length+' atendimento(s)</div></div></div><div class="agenda-list">'+(agendaCards||'<div class="empty"><div class="emptyico">▦</div><strong>Nenhum atendimento nesta data</strong><p>Escolha outro dia ou agende uma ordem de serviço.</p><button class="btn primary" data-action="new-service">＋ Agendar atendimento</button></div>')+'</div></section>';
const map='<section class="panel"><div class="panel-head"><div><h3>Mapa dos atendimentos</h3><div class="muted small">'+date(selected)+' · '+addresses.length+' endereço(s) com localização</div></div>'+(routeUrl?'<a class="btn primary" target="_blank" rel="noopener noreferrer" href="'+routeUrl+'">↗ Abrir rota no Google Maps</a>':'')+'</div><div class="map-note">Mapa interativo com marcadores. Para localizar os endereços, o sistema consulta o serviço público OpenStreetMap/Nominatim; o endereço digitado será enviado a esse serviço. É necessária conexão com a internet e endereços completos melhoram a precisão.</div><div class="service-leaflet-map" data-map-services="'+esc(JSON.stringify(addresses.map(x=>({id:x.service.id,title:x.service.title||"Atendimento",client:clientName(x.service.clientId),address:x.address,geocodeQuery:x.geocodeQuery}))))+'" role="region" aria-label="Mapa interativo dos atendimentos"></div><div class="map-stops">'+(mapCards||'<div class="empty"><div class="emptyico">⌖</div><strong>Sem endereços para mapear</strong><p>Cadastre o endereço do atendimento ou do cliente para montar a rota.</p></div>')+'</div></section>';
return '<div class="welcome"><div><h2>Ordens de serviço</h2><div class="muted">Planeje os atendimentos, confira a agenda e monte a rota do dia.</div></div></div>'+tabs+'<div class="agenda-datebar"><label for="agendaDateInput">Data selecionada</label><input type="date" id="agendaDateInput" value="'+selected+'"><button class="btn" data-agenda-view="day">Ver dia</button></div><div class="agenda-layout">'+(state.agendaView==="calendar"?calendar:state.agendaView==="map"?map:daily)+(state.agendaView==="day"?'<div class="agenda-side">'+map+'</div>':state.agendaView==="calendar"?daily:'')+'</div><section class="panel service-list-panel"><div class="panel-head"><h3>Todas as ordens</h3></div>'+searchBar("Buscar por serviço, cliente ou endereço…","new-service",'<select class="filter" id="filterSelect"><option value="all">Todos os status</option>'+["Agendado","Em andamento","Concluído","Cancelado"].map(x=>'<option '+(state.filter===x?"selected":"")+'>'+x+'</option>').join("")+'</select>')+(rows?table(["Serviço / cliente","Data","Status","Responsável","Valor","Ações"],rows):empty("⚒","Nenhuma ordem encontrada","Registre o próximo atendimento da equipe.","new-service","＋ Nova ordem"))+'</section>'
}
function getAiSpecEndpoint(){return String(localStorage.getItem("hydro-star-ai-spec-endpoint")||"").trim().replace(/\/+$/,"")}
function saveAiEndpoint(){const input=$("#aiSpecEndpoint");const status=$("#aiEndpointStatus");const value=String(input?.value||"").trim().replace(/\/+$/,"");if(value){try{const u=new URL(value);if(u.protocol!=="https:"){status.textContent="Use uma URL HTTPS para manter a conexão segura.";return}}catch{status.textContent="Informe uma URL válida do serviço de IA.";return}localStorage.setItem("hydro-star-ai-spec-endpoint",value)}else{localStorage.removeItem("hydro-star-ai-spec-endpoint")}if(status)status.textContent=value?"Endereço salvo neste navegador. A conexão será validada quando você gerar uma especificação.":"Conexão removida."}
async function generateSpecification(button){const form=button.closest("#recordForm");if(!form||form.dataset.type!=="quote")return;const endpoint=getAiSpecEndpoint();const status=form.querySelector("#specificationStatus");const output=form.querySelector("#quoteSpecification");if(!endpoint){if(status)status.textContent="Configure a URL do serviço em Dados e configurações.";return}const services=[...form.querySelectorAll('[data-line-kind="labor"]')].map(row=>({service:String(row.querySelector('[data-line="name"]')?.value||"").trim(),details:String(row.querySelector('[data-line="description"]')?.value||"").trim(),quantity:Number(row.querySelector('[data-line="quantity"]')?.value||0),unit:String(row.querySelector('[data-line="unit"]')?.value||"").trim()})).filter(x=>x.service||x.details);if(!services.length){if(status)status.textContent="Preencha pelo menos um item em Mão de obra / serviços.";return}const original=button.textContent;button.disabled=true;button.textContent="Gerando…";if(status)status.textContent="Preparando a especificação…";try{const response=await fetch(endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({services:services})});let payload={};try{payload=await response.json()}catch{}if(!response.ok)throw new Error(payload.error||("O serviço respondeu com erro ("+response.status+")."));const specification=String(payload.specification||"").trim();if(!specification)throw new Error("A IA não retornou uma especificação. Tente novamente.");output.value=specification;output.dispatchEvent(new Event("input",{bubbles:true}));if(status)status.textContent="Especificação gerada. Confira e salve o orçamento.";output.focus()}catch(error){if(status)status.textContent=error instanceof TypeError?"Não foi possível conectar. Confira a URL, a publicação do serviço e as permissões CORS.":(error.message||"Falha ao gerar a especificação.");}finally{button.disabled=false;button.textContent=original}}
function settingsPage(){const aiEndpoint=esc(localStorage.getItem("hydro-star-ai-spec-endpoint")||"");return '<div class="welcome"><div><h2>Dados e configurações</h2><div class="muted">Controle o backup, a integração de IA e entenda como seus dados são armazenados.</div></div></div><section class="panel" style="margin-bottom:16px"><div class="panel-head"><h3>IA para especificação de serviços</h3><span class="stat-icon">✦</span></div><p class="muted">Conecte o endpoint seguro do Gemini para gerar a especificação a partir do campo Mão de obra / serviços. O endereço é salvo apenas neste navegador.</p><div class="field full"><label for="aiSpecEndpoint">URL do serviço de IA</label><input id="aiSpecEndpoint" type="url" value="'+aiEndpoint+'" placeholder="https://seu-worker.workers.dev/generate-specification"></div><button type="button" class="btn primary" data-action="save-ai-endpoint">Salvar conexão</button><p id="aiEndpointStatus" class="muted small" aria-live="polite">A conexão só funcionará depois que o serviço seguro for publicado e configurado.</p><p class="muted small">Nunca coloque uma chave de API neste campo. A chave deve ficar como segredo no serviço de backend.</p></section><div class="notice"><strong>Importante sobre armazenamento local</strong>Os registros ficam neste navegador e neste perfil de usuário. Eles não são sincronizados com outros computadores nem ficam salvos no repositório GitHub. Se limpar os dados do navegador, os registros podem ser perdidos.</div><div class="settings-grid"><section class="panel"><div class="panel-head"><h3>Backup dos dados</h3><span class="stat-icon">⇩</span></div><p class="muted">Exporte clientes, orçamentos e ordens de serviço em um arquivo JSON para guardar como cópia de segurança.</p><button class="btn primary" data-action="export">⇩ Exportar backup</button><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><h3>Restaurar backup</h3><p class="muted">Importe um arquivo exportado anteriormente. Os registros com os mesmos identificadores serão atualizados; os demais serão adicionados.</p><button class="btn" data-action="import">⇧ Importar arquivo JSON</button></section><section class="panel"><div class="panel-head"><h3>Armazenamento</h3><span class="stat-icon">▣</span></div><div class="detail"><div class="detail-item"><small>Banco ativo</small><strong>'+(fallback?"localStorage":"IndexedDB")+'</strong></div><div class="detail-item"><small>Clientes</small><strong>'+state.clients.length+'</strong></div><div class="detail-item"><small>Orçamentos</small><strong>'+state.quotes.length+'</strong></div><div class="detail-item"><small>Ordens de serviço</small><strong>'+state.services.length+'</strong></div></div><p class="muted small" style="margin-top:14px">Não inclua informações altamente sensíveis. Use senha no computador e mantenha os backups em local protegido.</p><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><h3>Apagar todos os dados</h3><p class="muted">Remove os cadastros locais deste sistema neste navegador. Essa ação não pode ser desfeita sem backup.</p><button class="btn danger" data-action="clear">Apagar todos os dados locais</button></section></div>'}
function render(){const content=$("#content");$("#pageTitle").textContent=titles[state.page]||"Hydro Star CRM";$("#nav").querySelectorAll("button").forEach(b=>b.classList.toggle("active",b.dataset.page===state.page));content.innerHTML=({dashboard,clients:clientsPage,quotes:quotesPage,services:servicesPage,settings:settingsPage}[state.page]||dashboard)();$("#headerAdd").hidden=state.page==="settings";$("#headerAdd").textContent=state.page==="clients"?"＋ Novo cliente":state.page==="quotes"?"＋ Novo orçamento":state.page==="services"?"＋ Nova ordem":"＋ Novo cadastro";$("#headerAdd").onclick=()=>{if(state.page==="clients")openForm("client");else if(state.page==="quotes")openForm("quote");else if(state.page==="services")openForm("service");else showQuickModal()};if(state.page==="services")initServiceMaps()}
const geoCacheKey="hydro-star-crm-geocode-v3";
const sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function geocodeAddress(address){
 let cache={};try{cache=JSON.parse(localStorage.getItem(geoCacheKey)||"{}")}catch{}
 const key=String(address||"").trim().toLocaleLowerCase("pt-BR");if(!key)return null;
 if(cache[key]&&Number.isFinite(cache[key].lat)&&Number.isFinite(cache[key].lon))return cache[key];
 const parts=String(address).split(",").map(x=>x.trim()).filter(Boolean);
 const queries=[String(address).trim(),parts.filter(x=>!/^\\d{5}-?\\d{3}$/.test(x)).join(", "),parts.filter((x,i)=>i!==1).join(", ")].filter((q,i,a)=>q&&a.indexOf(q)===i);
 try{
  // Photon costuma funcionar melhor em navegadores sem exigir chave de API.
  for(const query of queries.slice(0,2)){
   try{
    const response=await fetch("https://photon.komoot.io/api/?limit=1&lang=pt&q="+encodeURIComponent(query));
    if(!response.ok)continue;
    const data=await response.json();const feature=data.features&&data.features[0];
    if(feature&&feature.geometry&&Array.isArray(feature.geometry.coordinates)){
     const point={lat:Number(feature.geometry.coordinates[1]),lon:Number(feature.geometry.coordinates[0])};
     const country=String(feature.properties?.country||"").toLocaleLowerCase("pt-BR");
     if(Number.isFinite(point.lat)&&Number.isFinite(point.lon)&&(!country||country.includes("brasil")||country.includes("brazil"))){
      cache[key]=point;try{localStorage.setItem(geoCacheKey,JSON.stringify(cache))}catch{}return point;
     }
    }
   }catch(error){console.warn("Photon não respondeu para o endereço:",error)}
  }
  // Alternativa: Nominatim, restrito ao Brasil.
  for(const query of queries){
   const response=await fetch("https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=br&q="+encodeURIComponent(query),{headers:{Accept:"application/json"}});
   if(!response.ok){console.warn("Nominatim respondeu",response.status);continue}
   const results=await response.json();if(!results.length)continue;
   const point={lat:Number(results[0].lat),lon:Number(results[0].lon)};
   if(!Number.isFinite(point.lat)||!Number.isFinite(point.lon))continue;
   cache[key]=point;try{localStorage.setItem(geoCacheKey,JSON.stringify(cache))}catch{}return point;
  }
  return null;
 }catch(error){console.warn("Não foi possível localizar o endereço:",error);return null}
}
async function initServiceMaps(){
 if(!window.L){
  document.querySelectorAll(".service-leaflet-map").forEach(el=>el.innerHTML='<div class="map-loading">Carregando biblioteca do mapa…</div>');
  if(window._hydroLeafletLoading)return;
  window._hydroLeafletLoading=true;
  if(!document.querySelector("link[data-hydro-leaflet-fallback]")){const css=document.createElement("link");css.rel="stylesheet";css.href="https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.css";css.dataset.hydroLeafletFallback="true";document.head.appendChild(css)}
  const script=document.createElement("script");script.src="https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.js";
  script.onload=()=>{window._hydroLeafletLoading=false;initServiceMaps()};
  script.onerror=()=>{window._hydroLeafletLoading=false;document.querySelectorAll(".service-leaflet-map").forEach(el=>el.innerHTML='<div class="map-loading">Não foi possível carregar o mapa neste navegador/rede. Use “Ver no mapa” ou “Abrir rota no Google Maps” abaixo.</div>')};
  document.head.appendChild(script);return
 }
 const containers=[...document.querySelectorAll(".service-leaflet-map")];
 for(const el of containers){
  if(el.dataset.mapReady==="true")continue;
  el.dataset.mapReady="true";
  let services=[];try{services=JSON.parse(el.dataset.mapServices||"[]")}catch{}
  const map=L.map(el,{scrollWheelZoom:false}).setView([-23.6,-45.4],9);
  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap</a>'}).addTo(map);
  const bounds=[];
  if(!services.length){el.innerHTML='<div class="map-loading">Nenhum endereço para exibir nesta data.</div>';continue}
  const markerIcon=L.divIcon({className:"hydro-map-marker-wrap",html:'<span class="hydro-map-marker">●</span>',iconSize:[28,28],iconAnchor:[14,14]});
  for(let i=0;i<services.length;i++){
   const service=services[i];if(!service.address)continue;
   const point=await geocodeAddress(service.geocodeQuery||service.address);
   if(point){
    const marker=L.marker([point.lat,point.lon],{icon:markerIcon}).addTo(map);
    const popup='<div class="map-popup"><strong>'+esc(service.title)+'</strong><div>'+esc(service.client)+'</div><small>'+esc(service.address)+'</small><div class="map-popup-actions"><button class="btn smallbtn" data-edit="service" data-id="'+esc(service.id)+'">Abrir atendimento</button> <a target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(service.geocodeQuery||service.address)+'">Google Maps</a></div></div>';
    marker.bindPopup(popup);bounds.push([point.lat,point.lon]);
   }
   if(i<services.length-1)await sleep(1100);
  }
  if(bounds.length){map.fitBounds(bounds,{padding:[28,28],maxZoom:14});if(bounds.length===1)map.setZoom(14)}
  else el.innerHTML='<div class="map-loading">Não foi possível localizar os endereços. Confira se estão completos, incluindo cidade e estado.</div>';
  setTimeout(()=>map.invalidateSize(),100);
 }
}
